import{_ as a,a0 as u,w as p,s,I as i,x as e,a1 as o,A as r,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"拯救者 Linux：我是如何給我的團隊引入 Linux 的 | LCTT x X-CMD","titleTemplate":false,"description":"拯救者 Linux：我是如何給我的團隊引入 Linux 的 | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"拯救者 Linux：我是如何給我的團隊引入 Linux 的 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"拯救者 Linux：我是如何給我的團隊引入 Linux 的 | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170714 Linux to the rescue How I introduced my organization to Linux","title":"拯救者 Linux：我是如何給我的團隊引入 Linux 的","tag":"201707","desc":""},"relativePath":"201707/20170714 Linux to the rescue How I introduced my organization to Linux.md","filePath":"[post].md"}'),x={name:"201707/20170714 Linux to the rescue How I introduced my organization to Linux.md"};function d(m,t,L,g,b,w){const n=u("Link");return p(),s("div",null,[t[19]||(t[19]=i("h1",{id:"拯救者-linux-我是如何給我的團隊引入-linux-的",tabindex:"-1"},[e("拯救者 Linux：我是如何給我的團隊引入 Linux 的 "),i("a",{class:"header-anchor",href:"#拯救者-linux-我是如何給我的團隊引入-linux-的","aria-label":"Permalink to “拯救者 Linux：我是如何給我的團隊引入 Linux 的”"},"​")],-1)),t[20]||(t[20]=i("blockquote",null,[i("p",null,"在項目早期就遇到公開的失敗後，一個著名大學的 IT 團隊決定將他們的 web 註冊系統部署到 Linux上，此舉幾乎將服務器的最大用户訪問量提高了 3 倍")],-1)),t[21]||(t[21]=i("p",null,[i("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/images/life/OSDC_Penguin_Image_520x292_12324207_0714_mm_v1a.png?itok=WfAkwbFy",alt:"Linux to the rescue: How I introduced my organization to Linux",title:"Linux to the rescue: How I introduced my organization to Linux"})],-1)),t[22]||(t[22]=i("p",null,"1998年，我在明尼蘇達大學為一個新的 web 團隊管理他們的服務器管理組。明尼蘇達大學是一個非常大的大學，個個院校擁有接近 6000 名在校大學生。當時學校是用一個上了年紀的大型機系統來做學生的檔案管理系統，這種系統已經過時了，所以需要做出改變。",-1)),i("p",null,[t[1]||(t[1]=e("這個系統不是 Y2K 類型的（LCTT 譯註：保存年份時只用兩位數，導致記錄 2000 年時計算機會記錄為 1900 年，詳見",-1)),o(n,{href:"https://stackoverflow.com/questions/18200744/what-does-y2k-compliant-mean"},{default:r(()=>[...t[0]||(t[0]=[e("What Does Y2K Compliant Mean?",-1)])]),_:1}),t[2]||(t[2]=e("），所以我們準備建立一個由仁科軟件公司來交付的新的學生檔案管理系統。這個新系統對明尼蘇達大學來説有很多作用，不僅能夠管理學生的檔案，還能提供其他的一些功能。然而它卻缺少了一項關鍵特性：你不能在你的瀏覽器上通過 web 來給你的班級進行註冊。",-1))]),t[23]||(t[23]=l('<p>按照今天的標準來看，這是一個重大的疏忽，但是在上世紀九十年代，互聯網還是一個新生概念。亞馬遜才建立不久，ebay 剛創業一年，google 呱呱墜地，Wikipedia 還沒有影兒。所以 1998 年仁科公司沒有支持 web 在線註冊課程這個功能也就不足為奇了。但是明尼蘇達大學作為 Gopher 網絡的發源地，並且給之前的大型機系統開發了一套 web 功能接口，我們覺得 web 在線註冊功能對於這個新的學生檔案管理系統是至關重要的。</p><p>我們在這個 web 團隊的任務就是去實現此管理系統的 web 在線註冊功能。</p><p>幸運的是，我們並不是孤軍奮戰。我們聯繫了 IBM ，在第二年一起開始來搭建這個新的 web 在線註冊系統。IBM 負責提供硬件和軟件環境來運行這個 web 系統：3 個運行最新的 AIX 系統（類 UNIX 操作系統）、IBM Java 和 IBM WebSphere 平台的 SP 電腦節點，並用一個 IBM 的負載均衡器來實現 3 個節點的負載分流。</p><p><img src="https://opensource.com/sites/default/files/resize/diagram-aix_0-700x363.png" alt="AIX network diagram" title="AIX network diagram"></p><p>在經過一年多的開發和測試後，我們的系統終於上線了！但不幸的是失敗卻接踵而至。</p><h3 id="負載過大" tabindex="-1">負載過大 <a class="header-anchor" href="#負載過大" aria-label="Permalink to “負載過大”">​</a></h3><p>在開發過程中，我們無法準確地模擬測試真實場景下許多學生同時登錄的場景。原因不是沒有測試環境，明尼蘇達大學有定製的 web 負載測試軟件包，而且 IBM 有自己的工具做補充，但是這個 web 系統在當時對我們來説實在是太陌生了，我們沒有意識到這些測試工具是不能滿足要求的。</p><p>通過數月的測試，我們將此 web 系統的預期負載量調整到 240 個併發用户。但不幸的是，我們實際的使用量卻是預期的兩倍左右，在第一天系統上線時，超過 400 名學生馬上同時登錄進系統，由於負載遠遠超出預期值，3 台 web 服務器直接宕機了。由於持續的高負載，服務器一直崩潰，只能不斷地重啓。一台剛重啓完，另一台又宕機重啓了，這種場景居然持續了一個月。</p><p>由於不能有效地通過 web 註冊，學生只能通過原來的方法來註冊：來到登記員的辦公室，拿着筆註冊，然後再出門。當地報紙也幸災樂禍地嘲諷道：&quot;電腦軟件的失敗強迫學生只能面對面地註冊！&quot;</p><p><img src="https://opensource.com/sites/default/files/resize/headlines-700x522.jpg" alt="Negative headlines about web registration crashes" title="Negative headlines about web registration crashes"></p><p>面對失敗這個事實，我們儘自己全力在下一個開發週期中來提高軟件性能，在之後 6 個月的時間裏，我們瘋狂地想去增強這套系統的負載能力。儘管增加了更多的代碼，調整了多次配置，還是不能支持更多的用户。盡力了，然而面對的還是失敗。</p><p>就如所料的，在下一個迭代週期後，迎接我們的還是失敗。服務器由於負載問題一次又一次地宕機。這一次新聞標題已經變成了：“web 註冊系統就是垃圾”。</p><p>在開始下一個為期 6 個月的迭代前，我們已經絕望了。沒有人知道服務器不停宕機的原因，我們已經預期這個問題現在是無解的。我們是要採取一些措施來搞定這個問題，但是怎麼做呢？以下是我們討論得出的方法：</p><h3 id="是否需要切換新的平台" tabindex="-1">是否需要切換新的平台? <a class="header-anchor" href="#是否需要切換新的平台" aria-label="Permalink to “是否需要切換新的平台?”">​</a></h3><p>IBM 當時引入了 Linux，給它的 Java 和 WebSphere 平台做了二次開發。所有產品都獲得了紅帽公司的 RHEL 認證，並且有幾個產品已經在我們的桌面系統上運行了。我們意識到了現在在 Linux 上已經有了完整的生態系統來運行我們的 web 管理系統，但是它能表現的比 AIX 更好嗎？</p><p>在搭建好一個測試服務器並進行基本的負載測試後，我們驚奇的發現一台 Linux 服務器能夠輕鬆地支持之前 3 台 AIX 服務器所不能支持的負載量，在相同的 web 代碼、IBM Java 和 WebSphere 平台下，單台 Linux 服務器能夠支持超過 200 個用户。</p><p>我們將這個消息告訴了登記員和 CIO，他們同意將 web 註冊系統切換到 Linux 平台上。雖然這是我們第一次在明尼蘇達大學跑 Linux，但是失敗已成習慣，反而無所畏懼了。AIX 只會失敗，Linux 卻是我們唯一的希望。</p><p>我們馬上基於 Linux 來進行開發。另一個組的同事也提供了幾台 Intel 服務器來給我們使用，我們給服務器裝上紅帽系統和相關的 IBM 組件，然後在新系統上進行了持續性的負載測試，令人欣喜的是，Linux 服務器沒有出現任何問題。</p><p>經過兩個月高強度的開發測試，我們的新系統終於上線了，而且是巨大的成功！在巨大的負載下，web 註冊系統在 Linux 的表現都堪稱完美。同時在線峯值甚至超過了 600 名用户。Linux 拯救了明尼蘇達大學的 web 註冊系統~</p><h3 id="成功的經驗" tabindex="-1">成功的經驗 <a class="header-anchor" href="#成功的經驗" aria-label="Permalink to “成功的經驗”">​</a></h3><p>當我回首這個項目時，我發現你可以用以下幾個點來向你的團隊介紹 Linux：</p><p>1、 <strong>解決問題, 不要自欺欺人</strong></p><p>當我們提議在企業中使用 Linux 時，並不是因為我們認為 Linux 很酷才使用它。當然，我們是 Linux 的愛好者並且已經在自己的環境中運行過它，但是我們在公司是為了解決問題的。能用 Linux 是因為我們的登記員和出資人同意 Linux 是解決問題的一個方法，而不僅僅是因為 Linux很酷我們想用它。</p><p>2、 <strong>儘可能小的去做改變</strong></p><p>我們的成功是建立在 IBM 已經基於 Linux 做出了它的 Java 和 WebSphere 產品的基礎上的。這能讓我們在將 web 系統從 AIX 切換到 Linux 上不用做過多的修改適配。兩者比起來只有硬件和操作系統改變了，其他系統相關的組件都保持了一致，這些都是保證平台切換成功的基石。</p><p><img src="https://opensource.com/sites/default/files/resize/cost-diagram-aix-700x363.png" alt="AIX cost diagram" title="AIX cost diagram"></p><p><img src="https://opensource.com/sites/default/files/resize/cost-diagram-linux-700x363.png" alt="Linux cost diagram" title="Linux cost diagram"></p><p>3、 <strong>誠實對待風險和回報</strong></p><p>我們的問題很明顯：web 註冊系統在前兩個迭代週期中都失敗了，而且很可能再次失敗。當我們將自己的想法（AIX 切換到 Linux）告訴出資方後，我們對其中的風險和回報是心知肚明的。如果我們什麼都不做，就只有失敗，如果我們嘗試切換到 Linux 平台，我們可能會成功，而且從最初的測試結果分析，成功的概率是高於失敗的。</p><p>而且就算在 Linux 平台下項目還是失敗了，我們也可以迅速地切換回 AIX 服務器。有了這些細緻的分析和措施，終於使登記員能夠安心讓我們試試 Linux。</p><p>4、 <strong>言簡意賅地交流</strong></p><p>在項目平台切換的過程中，我們做了一個整體計劃。我們在一張白紙上明確地寫下了我們計劃做什麼，為什麼要這麼做。這種方式的成功關鍵就在於計劃的簡短性。領導們不喜歡像看小説一樣來看技術性的主意，他們不想糾纏在技術細節中。所以我們有意地在執行層面上進行計劃安排，在框架層面上進行描述。</p><p>當我們在進行平台切換時，我們會定期的告訴出資人當前進展。當新系統成功完成後，我們每天都會提交更新，報告已經有多少學生成功通過此係統完成註冊和遇到的問題。</p><p>儘管這個項目已經過去了接近 20 年，但是其中的經驗教訓在今天仍然適用。儘管 Linux 在其中起了舉足輕重的作用，但是最重要的還是我們成功地將所有人的目標引導到解決共同的問題上。我認為這種經驗也可以運用到很多你所面對的事情當中。</p><p>（題圖 : Opensource.com）</p><hr><p>作者簡介：</p>',37)),i("p",null,[t[4]||(t[4]=e("Jim Hall -我是 FreeDOS 項目的發起者和協調人，我也在 GNOME 理事會中擔任董事。工作上我是明尼蘇達州拉姆西縣的首席信息官，空閒時間裏我為開源軟件的可用性做出相關的貢獻，並通過 ",-1)),o(n,{href:"https://en.wikipedia.org/wiki/Outreachy"},{default:r(()=>[...t[3]||(t[3]=[e("Outreachy",-1)])]),_:1}),t[5]||(t[5]=e("（為女性提供幫助的一項GNOME外展服務）來指導可用性測試。",-1))]),t[24]||(t[24]=i("hr",null,null,-1)),i("p",null,[t[7]||(t[7]=e("via: ",-1)),o(n,{href:"https://opensource.com/article/17/7/how-introduced-organization-linux"},{default:r(()=>[...t[6]||(t[6]=[e("https://opensource.com/article/17/7/how-introduced-organization-linux",-1)])]),_:1})]),i("p",null,[t[11]||(t[11]=e("作者：",-1)),o(n,{href:"https://opensource.com/users/jim-hall"},{default:r(()=>[...t[8]||(t[8]=[e("Jim Hall",-1)])]),_:1}),t[12]||(t[12]=e(" 譯者：",-1)),o(n,{href:"https://github.com/toyijiu"},{default:r(()=>[...t[9]||(t[9]=[e("吳霄/toyijiu",-1)])]),_:1}),t[13]||(t[13]=e(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:r(()=>[...t[10]||(t[10]=[e("wxy",-1)])]),_:1})]),i("p",null,[t[16]||(t[16]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[14]||(t[14]=[e("LCTT",-1)])]),_:1}),t[17]||(t[17]=e(" 原創編譯，",-1)),o(n,{href:"https://linux.cn/"},{default:r(()=>[...t[15]||(t[15]=[e("Linux中國",-1)])]),_:1}),t[18]||(t[18]=e(" 榮譽推出",-1))])])}const h=a(x,[["render",d]]);export{T as __pageData,h as default};
